typedef struct {
	unsigned int  ver;
	const char    *app_name;
	unsigned long flags;
	sc_thread_context_t *thread_ctx;
	int debug;
	FILE *debug_file;
} sc_context_param_t;

struct sc_card_error {
	unsigned int SWs;
	int errorno;
	const char *errorstr;
};

