// Build optional parameters for context creation
sc_context_param_t parm; parm.ver = 0; parm.app_name = FUZZ_PARAM_STR().c_str();
parm.flags = *FUZZ_PARAM(unsigned long); parm.thread_ctx = nullptr; parm.debug = (int)(*FUZZ_PARAM(unsigned int) & 1); parm.debug_file = nullptr;

// Create a new context
sc_context_t *ctx = nullptr;
int rc = sc_context_create(&ctx, &parm);
if (rc != 0 || !ctx) { FUZZ_BAIL(); }

// Track initialization for downstream stubs
FUZZ_SET_ATTR_INT(ctx, "initialized", 1);

// Validation: ensure created context is non-null
FUZZ_ASSERT(ctx != nullptr, "sc_context_create must return a non-null context on success");

// Releasing a previously created/established context. Runtime will drop it from pool after this stub.
int rc = sc_release_context(ctx);
(void)rc; // Some drivers may return 0 or error codes; we do not assert success here.

// Validation: dropping ctx from outputs ensures no double-free in subsequent calls.

// Deprecated entry that still creates a context; pass an application name
const char *app_name = FUZZ_PARAM_STR().c_str();
sc_context_t *ctx = nullptr;
int rc = sc_establish_context(&ctx, app_name);
if (rc != 0 || !ctx) { FUZZ_BAIL(); }

// Track state
FUZZ_SET_ATTR_INT(ctx, "initialized", 1);

// Validation: ensure non-null context on reported success
FUZZ_ASSERT(ctx != nullptr, "sc_establish_context must produce a context on success");

// Repair may update the ctx pointer; pass an lvalue pointer that starts with provided ctx
sc_context_t *local = ctx;
int rc = sc_context_repair(&local);
if (rc < 0) { FUZZ_BAIL(); }

// Propagate any pointer update back to outputs
ctx = local;
