import os
import random
import struct
from typing import List

# This generator targets two fuzzers:
# - sc_ctx_log_to_file: accepts filenames like "stderr", "stdout", or a random temp file path
# - sc_pkcs15_pubkey_from_spki_file: expects a DER-encoded SubjectPublicKeyInfo (SPKI) file
#
# We therefore generate a valid DER-encoded SPKI for various key types, with variations to
# exercise different parsing paths, while keeping the content valid. The buffer returned by
# generate() should be written by the harness to a file that FUZZ_PARAM_FILENAME() points to.
#
# We implement minimal DER/ASN.1 builders for SPKI structures:
# SubjectPublicKeyInfo ::= SEQUENCE {
#   algorithm AlgorithmIdentifier,
#   subjectPublicKey BIT STRING
# }
# AlgorithmIdentifier ::= SEQUENCE { algorithm OBJECT IDENTIFIER, parameters ANY DEFINED BY algorithm OPTIONAL }
#
# We support:
# - rsaEncryption (1.2.840.113549.1.1.1) params: NULL; subjectPublicKey: RSAPublicKey DER wrapped in BIT STRING
#   RSAPublicKey ::= SEQUENCE { modulus INTEGER, publicExponent INTEGER }
# - id-ecPublicKey (1.2.840.10045.2.1) params: namedCurve OBJECT IDENTIFIER; subjectPublicKey: ECPoint OCTET STRING inside BIT STRING
#   ECPoint is typically uncompressed 0x04 || X || Y
# - id-Ed25519 (1.3.101.112) params: absent; subjectPublicKey: OCTET STRING (32 bytes) inside BIT STRING
# - id-X25519  (1.3.101.110) params: absent; subjectPublicKey: OCTET STRING (32 bytes) inside BIT STRING
#
# The outputs are strictly <= 4096 bytes.

# --- Basic DER helpers ---

def _der_len(l: int) -> bytes:
    if l < 0x80:
        return bytes([l])
    s = []
    while l > 0:
        s.append(l & 0xFF)
        l >>= 8
    s = bytes(reversed(s))
    return bytes([0x80 | len(s)]) + s


def der_tlv(tag: int, content: bytes) -> bytes:
    return bytes([tag]) + _der_len(len(content)) + content


def der_seq(components: List[bytes]) -> bytes:
    content = b"".join(components)
    return der_tlv(0x30, content)


def der_oid_from_arcs(arcs: List[int]) -> bytes:
    if len(arcs) < 2:
        raise ValueError("OID must have at least two arcs")
    first = 40 * arcs[0] + arcs[1]
    body = [first]
    for a in arcs[2:]:
        # base-128 encoding with continuation bits
        if a == 0:
            body.append(0)
            continue
        stack = []
        while a > 0:
            stack.append(0x80 | (a & 0x7F))
            a >>= 7
        stack[-1] &= 0x7F
        body.extend(reversed(stack))
    return der_tlv(0x06, bytes(body))


def der_null() -> bytes:
    return b"\x05\x00"


def der_int(n: int) -> bytes:
    if n == 0:
        content = b"\x00"
    else:
        # big-endian two's complement positive
        tmp = bytearray()
        while n > 0:
            tmp.append(n & 0xFF)
            n >>= 8
        tmp = bytes(reversed(tmp))
        # ensure highest bit not set (avoid negative)
        if tmp[0] & 0x80:
            tmp = b"\x00" + tmp
        content = tmp
    return der_tlv(0x02, content)


def der_bit_string(bits: bytes, unused_bits: int = 0) -> bytes:
    return der_tlv(0x03, bytes([unused_bits]) + bits)


def der_octet_string(b: bytes) -> bytes:
    return der_tlv(0x04, b)

# --- Algorithm OIDs ---
OID_RSA = [1,2,840,113549,1,1,1]          # rsaEncryption
OID_EC_PUBLIC_KEY = [1,2,840,10045,2,1]   # id-ecPublicKey
OID_SECP256R1 = [1,2,840,10045,3,1,7]     # prime256v1
OID_SECP384R1 = [1,3,132,0,34]
OID_ED25519 = [1,3,101,112]
OID_X25519 = [1,3,101,110]

# --- Key builders ---

def build_spki_rsa(rng: random.Random) -> bytes:
    # Choose modulus bit length: 512, 768, 1024, or 2048
    bits = rng.choice([512, 768, 1024, 1536, 2048])
    nbytes = bits // 8
    # Create a random odd modulus-like integer with top bit set
    modulus = int.from_bytes(os.urandom(nbytes), 'big')
    modulus |= (1 << (bits - 1))  # top bit
    modulus |= 1  # odd
    # Public exponent typical 65537, sometimes 3
    exponent = rng.choice([65537, 3])

    rsapub = der_seq([der_int(modulus), der_int(exponent)])
    alg = der_seq([der_oid_from_arcs(OID_RSA), der_null()])
    spk = der_bit_string(rsapub)  # RSAPublicKey DER inside BIT STRING (no extra OCTET STRING)
    return der_seq([alg, spk])


def build_spki_ec(rng: random.Random) -> bytes:
    # Choose curve
    curve = rng.choice([OID_SECP256R1, OID_SECP384R1])
    field_len = 32 if curve == OID_SECP256R1 else 48
    # Uncompressed point: 0x04 || X || Y
    X = os.urandom(field_len)
    Y = os.urandom(field_len)
    ec_point = b"\x04" + X + Y

    alg = der_seq([der_oid_from_arcs(OID_EC_PUBLIC_KEY), der_oid_from_arcs(curve)])
    spk = der_bit_string(ec_point)
    return der_seq([alg, spk])


def build_spki_eddsa(rng: random.Random) -> bytes:
    # Ed25519 public key is 32 bytes
    pk = os.urandom(32)
    alg = der_seq([der_oid_from_arcs(OID_ED25519)])  # no params
    spk = der_bit_string(der_octet_string(pk))  # Per RFC 8410: BIT STRING of OCTET STRING
    return der_seq([alg, spk])


def build_spki_x25519(rng: random.Random) -> bytes:
    pk = os.urandom(32)
    alg = der_seq([der_oid_from_arcs(OID_X25519)])  # no params
    spk = der_bit_string(der_octet_string(pk))
    return der_seq([alg, spk])


def build_random_spki(rng: random.Random) -> bytes:
    choice = rng.choices(
        population=["rsa","ec","ed","x25519"],
        weights=[4, 3, 2, 1],
        k=1
    )[0]
    if choice == "rsa":
        return build_spki_rsa(rng)
    if choice == "ec":
        return build_spki_ec(rng)
    if choice == "ed":
        return build_spki_eddsa(rng)
    return build_spki_x25519(rng)

# Public API

def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    spki = build_random_spki(rng)

    # Ensure size constraint
    if len(spki) > 4096:
        # This should not happen with our sizes, but truncate gracefully (still valid DER if unlikely)
        # Better: rebuild smaller. We'll rebuild RSA 512 if oversized.
        spki = build_spki_rsa(rng)
        if len(spki) > 4096:
            spki = spki[:4096]

    return spki

import random
import struct
from typing import List

# Data type: arbitrary binary data
# Produce meaningful byte buffers for various OpenSC fuzz stubs that consume FUZZ_PARAM_STR.
# Keep inputs valid-looking (AIDs, TLV, DER SPKI/Cert shells, PKCS#15 IDs, etc.).

MAX_SIZE = 4096

# Basic DER helpers

def der_len(n: int) -> bytes:
    if n < 0x80:
        return bytes([n])
    s = []
    while n > 0:
        s.append(n & 0xFF)
        n >>= 8
    s.reverse()
    return bytes([0x80 | len(s)]) + bytes(s)


def der_tlv(tag: int, value: bytes) -> bytes:
    return bytes([tag]) + der_len(len(value)) + value


def der_integer(n: int) -> bytes:
    if n == 0:
        enc = b"\x00"
    else:
        tmp = []
        x = n
        while x > 0:
            tmp.append(x & 0xFF)
            x >>= 8
        tmp.reverse()
        enc = bytes(tmp)
        if enc[0] & 0x80:
            enc = b"\x00" + enc
    return der_tlv(0x02, enc)


def der_null() -> bytes:
    return der_tlv(0x05, b"")


def der_octet_string(data: bytes) -> bytes:
    return der_tlv(0x04, data)


def der_bit_string(bits: bytes) -> bytes:
    # prepend 0 unused bits count
    return der_tlv(0x03, b"\x00" + bits)


def der_oid(oid_nums: List[int]) -> bytes:
    # encode dotted OID: first two nodes: 40*x + y
    if len(oid_nums) < 2:
        oid_nums = [1, 3] + oid_nums
    first = 40 * oid_nums[0] + oid_nums[1]
    body = [first]
    for v in oid_nums[2:]:
        stack = [v & 0x7F]
        v >>= 7
        while v:
            stack.append(0x80 | (v & 0x7F))
            v >>= 7
        stack.reverse()
        body.extend(stack)
    return der_tlv(0x06, bytes(body))


def der_sequence(content: bytes) -> bytes:
    return der_tlv(0x30, content)


def der_set(content: bytes) -> bytes:
    return der_tlv(0x31, content)

# Builders

def build_aid(seed: int) -> bytes:
    rnd = random.Random(seed)
    prefixes = [
        bytes.fromhex("A000000003"),
        bytes.fromhex("A000000004"),
        bytes.fromhex("A000000396"),
        bytes.fromhex("A000000065"),
        bytes.fromhex("D27600012401"),  # OpenPGP
    ]
    p = rnd.choice(prefixes)
    rest_len = rnd.randint(max(0, 5 - len(p)), max(0, 16 - len(p)))
    rest = bytes(rnd.getrandbits(8) for _ in range(rest_len))
    return (p + rest)[:16]


def build_compact_tlv(seed: int) -> bytes:
    rnd = random.Random(seed)
    out = bytearray()
    for _ in range(rnd.randint(1, 8)):
        # upper nibble is tag, lower nibble is length (0..15)
        upper = rnd.choice([0x40, 0x50, 0x60, 0x70, 0x90])
        length = rnd.randint(0, 15)
        out.append((upper & 0xF0) | (length & 0x0F))
        out.extend(bytes(rnd.getrandbits(8) for _ in range(length)))
    return bytes(out)


def build_ber_tlv(seed: int) -> bytes:
    rnd = random.Random(seed)
    tlvs = []
    # 0x5A PAN ASCII digits
    pan = bytes(rnd.choice(b"0123456789") for _ in range(rnd.randint(8, 19)))
    tlvs.append(der_tlv(0x5A, pan))
    # 0x5F20 Cardholder Name
    name = rnd.choice([b"ALICE", b"BOB", b"CHARLIE", b"EID DEMO"])  # bytes
    tlvs.append(bytes([0x5F, 0x20]) + der_len(len(name)) + name)
    # 0x9F36 ATC (2 bytes)
    atc = struct.pack(">H", rnd.randrange(0, 0xFFFF))
    tlvs.append(bytes([0x9F, 0x36]) + der_len(len(atc)) + atc)
    return b"".join(tlvs)


def build_pkcs15_id(seed: int) -> bytes:
    rnd = random.Random(seed)
    l = rnd.randint(1, 20)
    return bytes(rnd.getrandbits(8) for _ in range(l))


def build_hex_string(seed: int) -> bytes:
    rnd = random.Random(seed)
    alphabet = "0123456789abcdef"
    s = ''.join(rnd.choice(alphabet) for _ in range(rnd.randint(2, 64)))
    return s.encode("ascii")


def build_base64(seed: int) -> bytes:
    rnd = random.Random(seed)
    b64chars = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    l = rnd.randint(4, 128)
    s = bytearray(rnd.choice(b64chars) for _ in range(l))
    pad = rnd.choice([0, 1, 2])
    if pad:
        s[-pad:] = b"=" * pad
    return bytes(s)


def build_symmetric_payload(seed: int) -> bytes:
    rnd = random.Random(seed)
    blocks = rnd.randint(1, 32)
    return bytes(rnd.getrandbits(8) for _ in range(blocks * 16))


def build_der_spki_rsa(seed: int) -> bytes:
    rnd = random.Random(seed)
    alg = der_sequence(der_oid([1, 2, 840, 113549, 1, 1, 1]) + der_null())
    n = der_integer((rnd.getrandbits(64) | 1) | 0xFFFFFFFFFFFF)
    e = der_integer(65537)
    rsa_pub = der_sequence(n + e)
    spk = der_bit_string(rsa_pub)
    spki = der_sequence(alg + spk)
    return spki


def build_der_spki_ec(seed: int) -> bytes:
    rnd = random.Random(seed)
    alg = der_sequence(
        der_oid([1, 2, 840, 10045, 2, 1]) + der_oid([1, 2, 840, 10045, 3, 1, 7])
    )
    x = bytes(rnd.getrandbits(8) for _ in range(32))
    y = bytes(rnd.getrandbits(8) for _ in range(32))
    pub = b"\x04" + x + y
    spk = der_bit_string(pub)
    return der_sequence(alg + spk)


def build_der_min_cert(seed: int) -> bytes:
    rnd = random.Random(seed)
    version = bytes([0xA0]) + der_len(len(der_integer(2))) + der_integer(2)
    serial = der_integer((rnd.getrandbits(32) | 1))
    sig_alg = der_sequence(der_oid([1, 2, 840, 113549, 1, 1, 11]) + der_null())
    name = der_sequence(der_set(der_sequence(der_oid([2, 5, 4, 3]) + der_tlv(0x0C, b"CN"))))

    def utc(t: bytes) -> bytes:
        return der_tlv(0x17, t)

    not_before = utc(b"250101000000Z")
    not_after = utc(b"350101000000Z")
    validity = der_sequence(not_before + not_after)
    spki = build_der_spki_rsa(seed + 1)
    tbs = der_sequence(version + serial + sig_alg + name + validity + name + spki)
    sig = der_bit_string(bytes(rnd.getrandbits(8) for _ in range(64)))
    cert = der_sequence(tbs + sig_alg + sig)
    return cert


def build_small_content(seed: int) -> bytes:
    rnd = random.Random(seed)
    l = rnd.randint(1, 256)
    return bytes(rnd.getrandbits(8) for _ in range(l))


def build_apdu_body_select_by_aid(seed: int) -> bytes:
    return build_aid(seed)


def build_oid_text(seed: int) -> bytes:
    rnd = random.Random(seed)
    parts = [str(rnd.choice([0, 1, 2]))]
    n = rnd.randint(2, 8)
    for _ in range(n):
        parts.append(str(rnd.randint(1, 2000)))
    return (".".join(parts)).encode("ascii")


def build_record_payload(seed: int) -> bytes:
    rnd = random.Random(seed)
    header = b"Record:" + struct.pack(">I", rnd.getrandbits(32)) + b"\n"
    body = bytes(rnd.getrandbits(8) for _ in range(rnd.randint(1, 256)))
    return header + body

BUILDERS = [
    build_apdu_body_select_by_aid,
    build_compact_tlv,
    build_ber_tlv,
    build_pkcs15_id,
    build_hex_string,
    build_base64,
    build_symmetric_payload,
    build_der_spki_rsa,
    build_der_spki_ec,
    build_der_min_cert,
    build_small_content,
    build_oid_text,
    build_record_payload,
]


def generate(seed: int) -> bytes:
    rnd = random.Random(seed)
    count = rnd.randint(1, 2)
    chosen = rnd.sample(BUILDERS, count)
    parts = []
    for i, b in enumerate(chosen):
        part = b(seed + 101 * (i + 1))
        parts.append(part)
    data = b"".join(parts)
    if len(data) > 1024:
        data = data[:1024]
    if not data:
        data = build_small_content(seed)
    return data[:MAX_SIZE]
